let
    SiteUrl = "https://harmar.sharepoint.com/sites/territorytracker",
    AllFiles = SharePoint.Files(SiteUrl, [ApiVersion = 15]),
    TargetFiles = Table.SelectRows(AllFiles, each Text.EndsWith([Name], "Periods-Days.xlsx") and Text.Contains([Folder Path], "/General/Slim Shady Files/")),
    _ensureAny = if Table.RowCount(TargetFiles) = 0 then error "Periods-Days.xlsx not found under /General/Slim Shady Files/." else null,
    TargetSorted = Table.Sort(TargetFiles, {{"Folder Path", Order.Ascending}}),
    FileBinary = TargetSorted{0}[Content],
    Imported = Excel.Workbook(FileBinary, true),
    Dates_Master_Table = Imported{[Item="Dates_Master", Kind="Table"]}[Data],
    #"Changed Type" = Table.TransformColumnTypes(Dates_Master_Table, {{"Date", type date}, {"Weekday #", Int64.Type}, {"Weekday", type text}, {"Workday", Int64.Type}, {"Year", Int64.Type}, {"Month #", Int64.Type}, {"Month", type text}, {"Day", Int64.Type}, {"Month & Year", type date}}),
    #"Removed Columns" = Table.RemoveColumns(#"Changed Type", {"Weekday #","Weekday","Year","Month #","Month","Day"}),
    #"Renamed Columns1" = Table.RenameColumns(#"Removed Columns", {{"Workday","Non workday = 1"}}),
    #"Added Custom5" = Table.AddColumn(#"Renamed Columns1", "Workday", each if [#"Non workday = 1"] = 0 then 1 else 0, Int64.Type),
    #"Removed Columns1" = Table.RemoveColumns(#"Added Custom5", {"Non workday = 1"}),
    Calendar = Table.SelectColumns(#"Removed Columns1", {"Date","Workday"}),
    #"Reordered Columns" = Table.ReorderColumns(#"Removed Columns1", {"Date","Workday","Month & Year"}),
    #"Added Custom" = Table.AddColumn(#"Reordered Columns", "Year-Month", each Date.ToText([#"Month & Year"], "yyyy-MM"), type text),
    #"Added Custom1" = Table.AddColumn(#"Added Custom", "Today", each Date.From(DateTime.LocalNow()), type date),
    #"Added Custom2" = Table.AddColumn(#"Added Custom1", "Today Year-Month", each Date.ToText([Today], "yyyy-MM"), type text),
    #"Added Custom3" = Table.AddColumn(#"Added Custom2", "Workdays", each if [#"Today Year-Month"] = [#"Year-Month"] then [Workday] else 0, Int64.Type),
    #"Added Custom4" = Table.AddColumn(#"Added Custom3", "Workdays Passed", each if [Date] < [Today] then [Workdays] else 0, Int64.Type),
    #"Removed Other Columns" = Table.SelectColumns(#"Added Custom4", {"Date","Today Year-Month","Workdays","Workdays Passed"}),
    #"Grouped Rows" = Table.Group(#"Removed Other Columns", {"Today Year-Month"}, {{"Total Workdays in Month", each List.Sum([Workdays]), type nullable number}, {"Workdays Passed in Month", each List.Sum([Workdays Passed]), type number}}),
    #"Added Custom6" = Table.AddColumn(#"Grouped Rows", "Elapsed", each [Workdays Passed in Month] / [Total Workdays in Month], type number),
    #"Removed Columns2" = Table.RemoveColumns(#"Added Custom6", {"Total Workdays in Month","Workdays Passed in Month"}),
    #"Added Custom7" = Table.AddColumn(#"Removed Columns2", "Current Month Flag", each 1, Int64.Type),
    #"Added Custom8" = Table.AddColumn(#"Added Custom7", "Today", each Date.From(DateTime.LocalNow()), type date),
    #"Added Custom9" = Table.AddColumn(#"Added Custom8", "Yesterday", each Date.AddDays([Today], -1), type date),
    YesterdayScalar = #"Added Custom9"{0}[Yesterday],
    YesterdayPYScalar = Date.AddYears(YesterdayScalar, -1),
    MonthStartCY = Date.StartOfMonth(YesterdayScalar),
    MonthEndCY = Date.EndOfMonth(YesterdayScalar),
    YearStartCY = Date.StartOfYear(YesterdayScalar),
    YearEndCY = Date.EndOfYear(YesterdayScalar),
    QtrStartCY = Date.StartOfQuarter(YesterdayScalar),
    MonthStartPY = Date.StartOfMonth(YesterdayPYScalar),
    MonthEndPY = Date.EndOfMonth(YesterdayPYScalar),
    YearStartPY = Date.StartOfYear(YesterdayPYScalar),
    YearEndPY = Date.EndOfYear(YesterdayPYScalar),
    QtrStartPY = Date.StartOfQuarter(YesterdayPYScalar),
    WDsMonthCY = List.Sum(Table.SelectRows(Calendar, each [Date] >= MonthStartCY and [Date] <= MonthEndCY)[Workday]),
    WDsMonthPassedCY = List.Sum(Table.SelectRows(Calendar, each [Date] >= MonthStartCY and [Date] <= YesterdayScalar)[Workday]),
    WDsYearCY = List.Sum(Table.SelectRows(Calendar, each [Date] >= YearStartCY and [Date] <= YearEndCY)[Workday]),
    WDsYearPassedCY = List.Sum(Table.SelectRows(Calendar, each [Date] >= YearStartCY and [Date] <= YesterdayScalar)[Workday]),
    PctThroughMonthCY = if WDsMonthCY = 0 then null else Number.From(WDsMonthPassedCY) / Number.From(WDsMonthCY),
    PctThroughYearCY = if WDsYearCY = 0 then null else Number.From(WDsYearPassedCY) / Number.From(WDsYearCY),
    WDsMonthPY = List.Sum(Table.SelectRows(Calendar, each [Date] >= MonthStartPY and [Date] <= MonthEndPY)[Workday]),
    WDsYearPY = List.Sum(Table.SelectRows(Calendar, each [Date] >= YearStartPY and [Date] <= YearEndPY)[Workday]),
    WDsQtrCY = List.Sum(Table.SelectRows(Calendar, each [Date] >= QtrStartCY and [Date] <= YesterdayScalar)[Workday]),
    WDsQtrPY = List.Sum(Table.SelectRows(Calendar, each [Date] >= QtrStartPY and [Date] <= YesterdayPYScalar)[Workday]),
    #"Added CY Metrics" = Table.AddColumn(#"Added Custom9", "% Through Month", each PctThroughMonthCY, type number),
    #"Added CY Metrics 2" = Table.AddColumn(#"Added CY Metrics", "% Through Year", each PctThroughYearCY, type number),
    #"Added CY Metrics 3" = Table.AddColumn(#"Added CY Metrics 2", "WDs Month", each WDsMonthCY, Int64.Type),
    #"Added CY Metrics 4" = Table.AddColumn(#"Added CY Metrics 3", "WDs Year", each WDsYearCY, Int64.Type),
    #"Added PY Fields" = Table.AddColumn(#"Added CY Metrics 4", "Yesterday Last Year", each YesterdayPYScalar, type date),
    #"Added PY Metrics 1" = Table.AddColumn(#"Added PY Fields", "WDs Month PY", each WDsMonthPY, Int64.Type),
    #"Added PY Metrics 2" = Table.AddColumn(#"Added PY Metrics 1", "WDs Year PY", each WDsYearPY, Int64.Type),
    #"Added Qtr CY" = Table.AddColumn(#"Added PY Metrics 2", "WDs Qtr CY", each WDsQtrCY, Int64.Type),
    #"Added Qtr PY" = Table.AddColumn(#"Added Qtr CY", "WDs Qtr PY", each WDsQtrPY, Int64.Type),
    #"Kept First Row" = Table.FirstN(#"Added Qtr PY", 1),
    #"Selected Columns Final" = Table.SelectColumns(#"Kept First Row", {"Today","Yesterday","Yesterday Last Year","% Through Month","% Through Year","WDs Month","WDs Year","WDs Month PY","WDs Year PY","WDs Qtr CY","WDs Qtr PY","Current Month Flag","Elapsed","Today Year-Month"})
in
    #"Selected Columns Final"